export class ZoneComponent {
  constructor(reclamationService) {
    this.reclamationService = reclamationService;
    this.agentName = 'Karim Mansour';
    this.agentRole = 'Agent Support Senior';
    this.currentTimeFormatted = '';
    this.isReclamationModalOpen = false;
    this.selectedReclamationDetails = null;
    this.showNotifications = false;
    this.notifications = [{
      id: 1,
      message: 'Nouvelle réclamation urgente (Fibre Optique)',
      time: 'Il y a 5 min',
      unread: true
    }, {
      id: 2,
      message: 'Technicien assigné à la Zone #04',
      time: 'Il y a 20 min',
      unread: true
    }];
    this.searchTerm = '';
    this.selectedStatusFilter = 'TOUS';
    this.loading = false;
    this.errorMessage = '';
    this.isClientModalOpen = false;
    this.selectedClient = null;
    this.selectedReclamationRef = '';
    // ➔ On fusionne en une seule source de vérité (reclamations)
    this.reclamations = [];
    this.isLoading = true;
    // Variables d'état pour la modale enrichie
    this.messagesList = [];
    this.reponseMessage = '';
    this.carnetNote = '';
    this.isClotureConfirmed = false;
  }
