      const matchesSearch = nom.toLowerCase().includes(search) || prenom.toLowerCase().includes(search) || numClient.toLowerCase().includes(search) || categorieCode.toLowerCase().includes(search) || reference.toLowerCase().includes(search) || sousCat.toLowerCase().includes(search) || description.toLowerCase().includes(search);
